			if !exists {
				idx, idxErr := snmp.DecodeIndexArcs(idxWire)
				if idxErr != nil {
					continue
				}
				key := string(idxWire)
				row = &IpAddressPrefixTableRow{}
				buffer[key] = row
				orderIdx = append(orderIdx, idx)
				orderKey = append(orderKey, key)
			}
			_, ok := tw.byCol[colID]
			if !ok {
				continue
			}
			var derr error
